e > 0 else zeros_block[0, j]\n                \n                # Extract 8 4-bit values\n                weights = tl.zeros((8,), dtype=tl.int32)\n                zeros = tl.zeros((8,), dtype=tl.int32)\n                \n                for k in range(8):\n                    shift = k * bits\n                    w = (qweight_val >> shift) & mask\n                    z = (zero_val >> shift) & mask\n                    weights = tl.store(weights, [k], w)\n                    zeros = tl.store(zeros, [k], z)\n                \n                # Reorder according to AWQ\n                weights_reordered = tl.zeros((8,), dtype=tl.int32)\n                zeros_reordered = tl.zeros((8,), dtype=tl.int32)\n                \n                for k in range(8):\n                    idx = reorder_indices[k]\n                    weights_reordered = tl.store(weights_reordered, [k], weights[idx])\n                    zeros_reordered = tl.store(zeros_reordered, [k], zeros[idx])\n                \n                # Dequantize each value\n                for k in range(8):\n                    # Calculate scale offset\n                    scale_row = row_idx[i] // group_size if group_size > 0 else 0\n                    scale_col = col_idx[j] * 8 + k\n                    \n                    # Load scale\n                    scale_offset = scale_row * (num_cols * 8) + scale_col\n                    scale = tl.load(scales_ptr + scale_offset)\n                    \n                    # Dequantize\n                    weight = weights_reordered[k]\n                    zero = zeros_reordered[k]\n                    dequantized = (weight - zero) * scale\n                    \n                    # Store result\n                    result_offset = row_idx[i] * (num_cols * 8) + scale_col\n                    tl.store(result_ptr + result_offset, dequantized)",
