     \n        # Accumulate\n        acc += tl.dot(a_block, b_dequantized)\n    \n    # Store result\n    c_offsets = rm[:, None] * N + rn[None, :]\n    tl.store(c_ptr + c_offsets, acc, mask=mask_m[:, None] & mask_n[None, :])",
        "awq_dequantize_triton": "def awq_dequantize_triton(qweight: torch.Tensor,\n                          scales: torch.Tensor,\n                          zeros: torch.Tensor,\n                          block_size_x: int = 32,\n                          block_size_y: int = 32) -> torch.Tensor:\n    \n    num_rows, num_cols = qweight.shape\n    actual_cols = num_cols * 8  # Each int32 stores 8 4-bit values\n    \n    # Determine group size\n    group_size = num_rows // scales.shape[0] if scales.shape[0] > 0 else -1\n    \n    # Allocate output\n    result = torch.empty((num_rows, actual_cols), dtype=torch.float16, device=qweight.device)\n    \n    # Launch kernel\n    grid = lambda META: (\n        triton.cdiv(num_cols, META['BLOCK_SIZE_X']),\n        triton.cdiv(num_rows, META['BLOCK_SIZE_Y']),\n    )\n    \n    awq_dequantize_kernel[grid](\n        qweight, scales, zeros, group_size, result,\n        num_cols, num_rows,\n        BLOCK_SIZE_X=block_size_x,\n        BLOCK_SIZE_Y=block_size_y\n    )\n    \n    return result",
        "awq_gemm_triton": "def awq_gemm_triton(input: torch.Tensor, qweight: torch.Tensor, \n                    scales: torch.Tensor, zeros: torch.Tensor,\n                    split_k_iters: int = 1) -> torch.Tensor:\n    \n    M, K = input.shape\n    N = qweight.shape[1] * 8  # Each int32 stores 8 4-bit values\n    \n    # Determine group size\n    group_size = K // scales.shape[0] if scales.shape[0] > 0 else -1\n    \n    # Allocate output\n    output = torch.empty((M, N), dtype=input.dtype, device=input.device)\n    \n    # Set block sizes\n    BLOCK_SIZE_M = 64\n    BLOCK_SIZE_N = 64\n    BLOCK_SIZE_K = 32\n    \n    # Launch kernel\n    grid = lambda META: (\n        triton.cdiv(M, META['BLOCK_SIZE_M']),\n        triton.cdiv(N, META['BLOCK_SIZE_N']),\n        split_k_iters,\n    )\n    \n    awq_gemm_kernel[grid](\n        input, qweight, output, zeros, scales,\n        M, N, K, group_size,\n        BLOCK_SIZE_M=BLOCK_SIZE_M,\n        BLOCK_SIZE_N=BLOCK_SIZE_N,\n        BLOCK_SIZE_K=BLOCK_SIZE_K,\n        SPLIT_K=split_k_iters\n    )\n    \n    return output"
